# R41: the one library shape (Songs, Progressions, Accompaniment, Exercises), from the rulings: search; place chips on
# top; Sort and filter with its count on the button, removable chips and Show n; sections that fold with counts,
# Recently used and Favourites first; a heart, never a star; + Add. The laptop is the library tree and a table.
import json

LIBJS = r'''
    const q = st.q ?? '', place = st.place ?? D.places[0], sort = st.sort ?? D.sorts[0], picked = st.picked ?? [], openMap = st.openMap ?? D.open, favs = st.favs ?? D.favs;
    const match = (r) => (!q || (r.t + ' ' + r.s).toLowerCase().includes(q.toLowerCase())) && (!picked.length || picked.some((f) => (r.tags || []).includes(f))) && (place === D.places[0] || (r.places || []).includes(place) || (place === 'Favourites' && favs.includes(r.t)));
    const toggleFav = (t) => set({ favs: favs.includes(t) ? favs.filter((x) => x !== t) : [...favs, t] });
    const sections = D.sections.map((g) => { const rows = g.rows.filter(match).map((r) => ({ ...r, fav: favs.includes(r.t), heart: favs.includes(r.t) ? '#B84A3E' : '#B4AAA0', heartFill: favs.includes(r.t) ? '#B84A3E' : 'none', canFav: !r.folder, pic: r.pic || 'none', ring: r.pic && !r.folder ? '0 0 0 1px #DAD1C8' : 'none', toggle: () => toggleFav(r.t) })); const o = openMap[g.g] !== false;
      return { ...g, rows, n: rows.length, isOpen: o, isShut: !o, chev: o ? 'rotate(0deg)' : 'rotate(-90deg)', fold: () => set({ openMap: { ...openMap, [g.g]: !o } }), show: rows.length > 0 }; }).filter((g) => g.show);
    const shown = sections.reduce((a, g) => a + g.n, 0);
    const allOpen = sections.every((g) => g.isOpen);
    const tree = D.sections.flatMap((g) => g.rows.filter((r) => r.folder).map((r) => ({ g: r.t, n: r.v || r.s.split(' ')[0], c: r.c }))); const placesT = D.places.map((l) => ({ l, bg: l === place ? '#E8E1D8' : 'transparent', fw: l === place ? 700 : 500, pick: () => set({ place: l }) }));
    return { ...common(st, set), q, setQ: (e) => set({ q: e.target.value }), sections, shown, empty: shown === 0, notEmpty: shown > 0,
      places: chipsOf(D.places, place, (l) => set({ place: l })), placeName: place,
      sorts: seg(D.sorts, sort, (l) => set({ sort: l })), sortName: sort,
      filters: D.filters.map((f) => ({ name: f.name, opts: f.opts.map(([l, n]) => ({ l, n, on: picked.includes(l), bg: picked.includes(l) ? '#332921' : '#FEFDFB', fg: picked.includes(l) ? '#FEFDFB' : '#332921', pick: () => set({ picked: picked.includes(l) ? picked.filter((x) => x !== l) : [...picked, l] }) })) })),
      chosen: picked.map((l) => ({ l, drop: () => set({ picked: picked.filter((x) => x !== l) }) })), hasChosen: picked.length > 0, count: picked.length ? String(picked.length) : '', countOn: picked.length > 0,
      reset: () => set({ picked: [], sort: D.sorts[0] }), showN: 'Show ' + shown, foldAll: () => set({ openMap: Object.fromEntries(D.sections.map((g) => [g.g, !allOpen])) }), foldLabel: allOpen ? 'Close all' : 'Open all',
      sortOn: st.sheet === 'sort', addOn: st.sheet === 'add', openSort: () => set({ sheet: 'sort' }), openAdd: () => set({ sheet: 'add' }), tree, hasTree: tree.length > 0, placesT, shelf: D.shelf || [], hasShelf: !!(D.shelf || []).length,
      clearQ: () => set({ q: '', picked: [], place: D.places[0] }),
'''
HEARTI = f'<svg viewBox="0 0 24 24" width="20" height="20" fill="{{{{r.heartFill}}}}" stroke="{{{{r.heart}}}}" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.6-7 10-7 10Z"></path></svg>'
def LIB_ROW(laptop=False):
    return (f'<div style="min-height: 64px; display: flex; align-items: center; gap: 12px; padding: 8px 4px 8px 12px; box-shadow: inset 0 -1px 0 {LINE}">'
            f'<a href="{{{{r.href}}}}" style="flex: 1; min-width: 0; display: flex; align-items: center; gap: 12px; color: {INK}; text-decoration: none"><span style="flex: none; width: 44px; height: 44px; border-radius: 10px; overflow: hidden; background: {{{{r.c}}}}; background-image: {{{{r.pic}}}}; background-size: cover; box-shadow: {{{{r.ring}}}}; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; color: {{{{r.ic}}}}">{{{{r.i}}}}</span>'
            f'<span style="flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px"><span style="font-size: 16px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis">{{{{r.t}}}}</span><span style="font-size: 14px; color: {SOFT}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis">{{{{r.s}}}}</span></span>'
            f'<span style="flex: none; font-size: 14px; color: {SOFT}; font-variant-numeric: tabular-nums">{{{{r.v}}}}</span></a>'
            f'<sc-if value="{{{{r.canFav}}}}" hint-placeholder-val="{{{{true}}}}"><button type="button" aria-label="Favourite" aria-pressed="{{{{r.fav}}}}" onClick="{{{{r.toggle}}}}" style="flex: none; width: 44px; height: 44px; border: 0; background: transparent; display: flex; align-items: center; justify-content: center">{HEARTI}</button></sc-if><sc-if value="{{{{r.folder}}}}" hint-placeholder-val="{{{{false}}}}"><span style="flex: none; width: 32px; display: flex; color: {SOFT}">{CHEV_R}</span></sc-if></div>')
def SEARCHROW():
    return (f'<div style="flex: none; display: flex; gap: 8px"><label style="flex: 1; min-width: 0; height: 44px; border-radius: 12px; background: {FILL}; display: flex; align-items: center; gap: 8px; padding: 0 12px; color: {SOFT}">{SEARCH}<input value="{{{{q}}}}" onInput="{{{{setQ}}}}" placeholder="Search" aria-label="Search" style="flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font: inherit; font-size: 16px; color: {INK}"></label>'
            f'<button type="button" aria-label="Sort and filter" onClick="{{{{openSort}}}}" style="position: relative; flex: none; width: 44px; height: 44px; border: 0; border-radius: 12px; background: {FILL}; color: {INK}; display: flex; align-items: center; justify-content: center">{GEARI.replace("22", "20")}<sc-if value="{{{{countOn}}}}" hint-placeholder-val="{{{{false}}}}"><span style="position: absolute; top: -5px; right: -5px; min-width: 18px; height: 18px; border-radius: 9px; background: {INK}; color: {SHEET}; font-size: 11px; font-weight: 700; display: flex; align-items: center; justify-content: center">{{{{count}}}}</span></sc-if></button></div>')
CHOSEN = f'<sc-if value="{{{{hasChosen}}}}" hint-placeholder-val="{{{{false}}}}"><div style="display: flex; flex-wrap: wrap; gap: 6px"><sc-for list="{{{{chosen}}}}" as="c" hint-placeholder-count="1"><button type="button" onClick="{{{{c.drop}}}}" aria-label="Remove {{{{c.l}}}}" style="height: 30px; padding: 0 10px; border: 0; border-radius: 15px; background: {INK}; color: {SHEET}; font: inherit; font-size: 13px; font-weight: 600">{{{{c.l}}}} ✕</button></sc-for></div></sc-if>'
def SECTIONS(shelf_html=''):
    return (f'{shelf_html}'
            f'<sc-for list="{{{{sections}}}}" as="g" hint-placeholder-count="3"><section style="display: flex; flex-direction: column; gap: 6px"><button type="button" aria-expanded="{{{{g.isOpen}}}}" onClick="{{{{g.fold}}}}" style="align-self: flex-start; height: 44px; margin: -5px 0; border: 0; background: transparent; padding: 0 4px; display: flex; align-items: center; gap: 6px; color: {INK}; font: inherit"><span style="font-size: 20px; font-weight: 700">{{{{g.g}}}}</span><span style="font-size: 15px; color: {SOFT}">{{{{g.n}}}}</span><span style="display: flex; color: {SOFT}; transform: {{{{g.chev}}}}">{CHEV_D}</span></button>'
            f'<sc-if value="{{{{g.isOpen}}}}" hint-placeholder-val="{{{{true}}}}"><div style="border-radius: 12px; background: {SHEET}; box-shadow: 0 0 0 1px {LINE}; overflow: hidden"><sc-for list="{{{{g.rows}}}}" as="r" hint-placeholder-count="3">{LIB_ROW()}</sc-for></div></sc-if></section></sc-for>'
            f'<sc-if value="{{{{empty}}}}" hint-placeholder-val="{{{{false}}}}"><div style="padding: 40px 12px; display: flex; flex-direction: column; align-items: center; gap: 10px; text-align: center"><span style="font-size: 17px; font-weight: 600">Nothing matches</span><span style="font-size: 15px; color: {SOFT}">Try fewer filters or another word.</span>{BTN("Clear search and filters", "clearQ", kind="quiet", h=44, grow=False)}</div></sc-if>')
SORTSHEET_BODY = (f'{CAPS("Sort by")}{SEGC("sorts", 34, 13)}<sc-for list="{{{{filters}}}}" as="f" hint-placeholder-count="2">{CAPS("{{f.name}}")}<div style="display: flex; flex-wrap: wrap; gap: 8px"><sc-for list="{{{{f.opts}}}}" as="o" hint-placeholder-count="4"><button type="button" aria-pressed="{{{{o.on}}}}" onClick="{{{{o.pick}}}}" style="height: 36px; padding: 0 12px; border: 0; border-radius: 18px; background: {{{{o.bg}}}}; color: {{{{o.fg}}}}; box-shadow: 0 0 0 1px {LINE}; font: inherit; font-size: 14px; font-weight: 600">{{{{o.l}}}} <span style="opacity: .6; font-weight: 500">{{{{o.n}}}}</span></button></sc-for></div></sc-for>'
                  f'<div style="display: flex; gap: 10px; margin-top: 6px">{BTN("Reset", "reset", kind="quiet", grow=False)}{BTN("{{showN}}", "closeSheet")}</div>')

def library(stem, title, D, back='', back_l='', soft='', right_extra='', soft_href='', root='', section='Practice', shelf_phone='', shelf_laptop='', table_cols=(('Name', 't', 3), ('', 's', 4), ('', 'v', 1.4)), add_items=(), more_rows=()):
    script = js('    const D = ' + json.dumps(D, ensure_ascii=False) + ';\n' + LIBJS + '\n    };')
    add = IB('Add', PLUS, 'openAdd') if add_items else ''
    addbody = GROUP(*[('link', a, '', h) for a, h in add_items]) if add_items else ''
    more = GROUP(*more_rows) if more_rows else ''
    sheets = BSHEET('sortOn', 'Sort and filter', SORTSHEET_BODY) + (BSHEET('addOn', 'Add', addbody) if add_items else '') + (BSHEET('moreOn', title, more) if more_rows else '')
    body = f'''{TOP(back, '', right_extra + add + (DOTS() if more_rows else ''))}
{LARGE(title, soft=(f'<a href="{soft_href}.dc.html" style="color: inherit; text-decoration: none">{soft}</a>' if soft_href else soft))}
<main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; padding: 0 16px {130 if root else 40}px; display: flex; flex-direction: column; gap: 14px">
{SEARCHROW()}{CHIPS('places')}{CHOSEN}{SECTIONS(shelf_phone)}
</main>{TABBAR(root) if root else ''}'''
    phone(stem, title + ', phone', body, script, sheets)
    # laptop: the tree and a table
    cols = ''.join(f'<span style="flex: {w}; min-width: 0; font-size: 13px; font-weight: 600; color: {SOFT}">{h}</span>' for h, _, w in table_cols)
    cells = ''.join(f'<span style="flex: {w}; min-width: 0; font-size: {15 if k == "t" else 14}px; font-weight: {600 if k == "t" else 400}; color: {INK if k == "t" else SOFT}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis">{{{{r.{k}}}}}</span>' for _, k, w in table_cols)
    table = (f'<div style="display: flex; gap: 16px; padding: 0 12px 8px 68px; box-shadow: inset 0 -1px 0 {LINE}">{cols}<span style="width: 44px"></span></div>'
             f'<sc-for list="{{{{sections}}}}" as="g" hint-placeholder-count="3"><button type="button" onClick="{{{{g.fold}}}}" style="height: 40px; border: 0; background: transparent; padding: 0 4px; display: flex; align-items: center; gap: 6px; color: {INK}; font: inherit; margin-top: 8px"><span style="display: flex; color: {SOFT}; transform: {{{{g.chev}}}}">{CHEV_D}</span><span style="font-size: 16px; font-weight: 700">{{{{g.g}}}}</span><span style="font-size: 14px; color: {SOFT}">{{{{g.n}}}}</span></button>'
             f'<sc-if value="{{{{g.isOpen}}}}" hint-placeholder-val="{{{{true}}}}"><sc-for list="{{{{g.rows}}}}" as="r" hint-placeholder-count="3"><div style="height: 56px; display: flex; align-items: center; gap: 16px; padding: 0 0 0 12px; border-radius: 10px; box-shadow: inset 0 -1px 0 {FILL}"><a href="{{{{r.href}}}}" style="flex: 1; min-width: 0; display: flex; align-items: center; gap: 16px; color: {INK}; text-decoration: none"><span style="flex: none; width: 40px; height: 40px; border-radius: 9px; background: {{{{r.c}}}}; background-image: {{{{r.pic}}}}; background-size: cover; box-shadow: {{{{r.ring}}}}; display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700; color: {{{{r.ic}}}}">{{{{r.i}}}}</span>{cells}</a><sc-if value="{{{{r.canFav}}}}" hint-placeholder-val="{{{{true}}}}"><button type="button" aria-label="Favourite" onClick="{{{{r.toggle}}}}" style="flex: none; width: 44px; height: 44px; border: 0; background: transparent; display: flex; align-items: center; justify-content: center">{HEARTI}</button></sc-if><sc-if value="{{{{r.folder}}}}" hint-placeholder-val="{{{{false}}}}"><span style="flex: none; width: 44px; display: flex; justify-content: center; color: {SOFT}">{CHEV_R}</span></sc-if></div></sc-for></sc-if></sc-for>')
    tree = (f'<nav aria-label="{title}" class="nos" style="min-height: 0; overflow-y: auto; padding: 24px 12px; box-shadow: 1px 0 0 {LINE}; display: flex; flex-direction: column; gap: 2px">{CAPS("Places")}'
            f'<sc-for list="{{{{placesT}}}}" as="p" hint-placeholder-count="4"><button type="button" onClick="{{{{p.pick}}}}" style="height: 40px; border: 0; border-radius: 9px; background: {{{{p.bg}}}}; color: {INK}; text-align: left; padding: 0 12px; font: inherit; font-size: 15px; font-weight: {{{{p.fw}}}}">{{{{p.l}}}}</button></sc-for>'
            f'<sc-if value="{{{{hasTree}}}}" hint-placeholder-val="{{{{true}}}}"><div style="height: 14px"></div>{CAPS("Folders")}<sc-for list="{{{{tree}}}}" as="t" hint-placeholder-count="4"><div style="height: 40px; display: flex; align-items: center; gap: 10px; padding: 0 12px; font-size: 15px"><span style="flex: none; width: 10px; height: 10px; border-radius: 3px; background: {{{{t.c}}}}"></span><span style="flex: 1">{{{{t.g}}}}</span><span style="color: {SOFT}; font-variant-numeric: tabular-nums">{{{{t.n}}}}</span></div></sc-for></sc-if></nav>')
    lb = f'<a href="{back_l}" aria-label="Back" style="width: 44px; height: 44px; margin-left: -10px; display: flex; align-items: center; justify-content: center; color: {INK}; text-decoration: none">{CHEV_L}</a>' if back_l else ''
    main = (f'<div style="flex: 1; min-height: 0; display: grid; grid-template-columns: 240px minmax(0, 1fr)">{tree}<div style="min-width: 0; min-height: 0; display: flex; flex-direction: column">'
            f'<header style="flex: none; display: flex; align-items: center; gap: 12px; padding: 20px 32px 12px 40px">{lb}<h1 style="margin: 0; font-size: 30px; font-weight: 700">{title}</h1>{("<span style=\"font-size: 30px; font-weight: 700; color: " + LINE + "\">" + (('<a href="' + soft_href + 'Laptop.dc.html" style="color: inherit; text-decoration: none">' + soft + '</a>') if soft_href else soft) + "</span>") if soft else ""}<span style="flex: 1"></span><div style="width: 340px">{SEARCHROW()}</div>{right_extra.replace('.dc.html', 'Laptop.dc.html')}{add}{DOTS() if more_rows else ""}</header>'
            f'<div style="padding: 0 40px">{CHOSEN}</div><main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; padding: 4px 40px 40px; display: flex; flex-direction: column; gap: 6px"><div style="margin-bottom: 18px">{shelf_laptop}</div>{table}'
            f'<sc-if value="{{{{empty}}}}" hint-placeholder-val="{{{{false}}}}"><p style="text-align: center; color: {SOFT}; font-size: 16px; padding: 40px">Nothing matches. Try fewer filters or another word.</p></sc-if></main></div></div>')
    pops = POPOVER('sortOn', 'Sort and filter', SORTSHEET_BODY, 'right: 120px; top: 70px', 400) + (POPOVER('addOn', 'Add', addbody, 'right: 80px; top: 70px', 320) if add_items else '') + (POPOVER('moreOn', title, more) if more_rows else '')
    Dl = json.loads(json.dumps(D))
    for g in Dl['sections']:
        for r in g['rows']:
            if r.get('href', '#') != '#': r['href'] = r['href'].replace('.dc.html', 'Laptop.dc.html')
    laptop('Laptop' if stem == 'Main' else stem + 'Laptop', title + ', laptop', main, '', js('    const D = ' + json.dumps(Dl, ensure_ascii=False) + ';\n' + LIBJS + '\n    };'), pops, section)
